-- TABELA servprod

DROP TABLE IF EXISTS `servprod`;
CREATE TABLE `servprod` (
  `id` int NOT NULL AUTO_INCREMENT,
  `Nome` varchar(400) COLLATE utf8mb4_general_ci NOT NULL,
  `Tipo` int NOT NULL,
  `Inativo` int NOT NULL,
  `Descricao` varchar(350) COLLATE utf8mb4_general_ci NOT NULL,
  `Unidade` varchar(20) COLLATE utf8mb4_general_ci NOT NULL,
  `ValorCusto` decimal(10,2) NOT NULL,
  `ValorVenda` decimal(10,2) NOT NULL,
  `idEmpresa` int NOT NULL,
  `Codigo` int NOT NULL,
  `DataAlt` datetime DEFAULT NULL,
  `SolicitaVeiculo` int NOT NULL,
  `MetaMensal` int NOT NULL DEFAULT '0',
  `Grupo` int DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=143 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

